={{ (() => {
  // Port of harness/checks.py check_length + _length_target: an explicit floor or ceiling is exact, a target or range gets ±15%.
  const brief = $('Build Draft Input').first().json.brief || {};
  const length = brief.length;
  const content = String($json.output.draft.content || '');
  const tol = 0.15;
  const UNIT = /(\d+(?:[,.]\d+)*k?)\s*\+?\s*(?:(?:-|–|—|to)\s*(\d+(?:[,.]\d+)*k?)\s*)?[\s-]*(words?|characters?|chars?)\b/gi;
  const BETWEEN = /\bbetween\s+(\d+(?:[,.]\d+)*k?)\s+and\s+(\d+(?:[,.]\d+)*k?)\s*(words?|characters?|chars?)\b/i;
  const AT_MOST = /≤|<=|<(?!=)|\bmax(?:imum)?\b|\bup to\b|\bno (?:more|longer) than\b|\bnot (?:more than|to exceed|exceed(?:ing)?|over|above)\b|(?:\b(?:never|do not|must not|cannot|can not)|n't|can’t) exceed\b|(?:\bnot|\bcannot|n't|’t) be (?:more than|over|above|greater than|longer than)\b|(?:\bnot(?: to)?|n't|’t) go (?:over|above|beyond)\b|\bwithout exceeding\b|\bnot longer than\b|\bat most\b|\bunder\b/i;
  const AT_LEAST = /≥|>=|>(?!=)|\bmin(?:imum)?\b|\bat least\b|\b(?:no|not) (?:less|fewer) than\b/i;
  const AT_MOST_BEFORE = /(?<!no )(?<!not )\b(?:less than|fewer than|below|within)\s*(?:about\s+|around\s+|~\s*)?$/i;
  const AT_LEAST_BEFORE = /(?<!not )(?<!never )(?<!n't )(?<!no )\b(?:more than|over|above|exceeds?)\s*(?:about\s+|around\s+|~\s*)?$/i;
  const AT_MOST_AFTER = /^\s*or\s+(?:less|fewer)\b/i;
  const AT_LEAST_AFTER = /^\s*or\s+more\b/i;
  const PER_AFTER = /^[\s)\],.;:]*(?:each|apiece|per\b|\/)/i;
  const PER_BEFORE = /(?:\b(?:each|every)\b[^,;.]{0,20}|\b(?:\d+|one|two|three|four|five|six|seven|eight|nine|ten)\s+[a-z]+s\s+(?:of|at)\s+(?:[a-z~]+\s+){0,2})$/i;
  const AFTER_CEILING = /^[\s(,–-]*(?:max(?:imum)?|at most|tops|up to|no more than)\b(?!\s*\d)/i;
  const AFTER_FLOOR = /^[\s(,–-]*(?:min(?:imum)?|at least)\b(?!\s*\d)/i;
  const CEILING_NUM = /(?:^|[,;(])\s*(?:but\s+|and\s+)?(?:(?:max(?:imum)?|at most|up to|no more than)\s*(?:of\s*)?(\d+(?:[,.]\d+)*k?)\s*(?:words?|characters?|chars?)?\s*(?:[).,;]|$)|(\d+(?:[,.]\d+)*k?)\s*max(?:imum)?\b)/i;
  const FLOOR_NUM = /(?:^|[,;(])\s*(?:but\s+|and\s+)?(?:(?:min(?:imum)?|at least)\s*(?:of\s*)?(\d+(?:[,.]\d+)*k?)\s*(?:words?|characters?|chars?)?\s*(?:[).,;]|$)|(\d+(?:[,.]\d+)*k?)\s*min(?:imum)?\b)/i;
  const NOUN_LIMIT = /\b(?:max(?:imum)?|min(?:imum)?|at most|at least|up to|no more than|under|over)\s*\d[\d,.]*\s+(?!words?\b|characters?\b|chars?\b)[a-z]+\b/gi;
  const SENT = /(?<=[.!?;])\s+|\n/;
  const parseNum = s => {
    let t = s.toLowerCase();
    if (/^\d{1,3}(?:\.\d{3})+$/.test(t)) t = t.replace(/\./g, '');
    t = t.replace(/,/g, '');
    const k = t.endsWith('k');
    let v = Number(k ? t.slice(0, -1) : t);
    if (!Number.isFinite(v)) return null;
    if (k) v *= 1000;
    return v > 1e12 ? null : Math.trunc(v);
  };
  const lastSentence = s => s.split(SENT).pop();
  const firstSentence = s => s.split(SENT)[0];
  const unitOf = m => m[3][0].toLowerCase() === 'c' ? 'characters' : 'words';
  const target = (() => {
    if (typeof length === 'number') return Number.isInteger(length) && length > 0 ? ['words', Math.trunc(length * (1 - tol)), Math.ceil(length * (1 + tol))] : null;
    if (typeof length !== 'string') return null;
    const text = length.replace(/\b(max|min)\./gi, '$1');
    const between = BETWEEN.exec(text);
    const ms = between ? [between] : Array.from(text.matchAll(UNIT));
    if (!ms.length) return null;
    const unit = unitOf(ms[0]);
    let low = 0, high = null, found = false, plain = 0;
    for (let i = 0; i < ms.length; i++) {
      const m = ms[i];
      if (unitOf(m) !== unit) continue;
      const end = m.index + m[0].length;
      // Each count reads only the text between its neighbouring counts, cut to its own sentence.
      let gap = text.slice(i ? ms[i - 1].index + ms[i - 1][0].length : 0, m.index);
      if (i) {
        const clause = /[,;]\s*/.exec(gap);
        if (clause) gap = gap.slice(clause.index + clause[0].length);
      }
      const before = lastSentence(gap).replace(NOUN_LIMIT, '');
      const after = firstSentence(text.slice(end, i + 1 < ms.length ? ms[i + 1].index : text.length));
      const hint = firstSentence(text.slice(end));
      if (PER_AFTER.test(after.slice(0, 16)) || PER_BEFORE.test(before)) continue;
      const n1 = parseNum(m[1]);
      const n2 = m[2] ? parseNum(m[2]) : null;
      if (n1 === null || (m[2] && n2 === null)) continue;
      let lo, hi;
      if (n2 !== null) {
        lo = Math.trunc(Math.min(n1, n2) * (1 - tol));
        hi = Math.ceil(Math.max(n1, n2) * (1 + tol));
      } else if (AT_MOST.test(before) || AT_MOST_BEFORE.test(before) || AFTER_CEILING.test(hint) || AT_MOST_AFTER.test(after)) {
        lo = 0;
        hi = n1;
      } else if (m[0].includes('+') || AT_LEAST.test(before) || AT_LEAST_BEFORE.test(before) || AFTER_FLOOR.test(hint) || AT_LEAST_AFTER.test(after)) {
        lo = n1;
        hi = null;
      } else {
        lo = Math.trunc(n1 * (1 - tol));
        hi = Math.ceil(n1 * (1 + tol));
        plain += 1;
      }
      const floorMatch = FLOOR_NUM.exec(after);
      const ceilingMatch = CEILING_NUM.exec(after);
      const floor = floorMatch ? parseNum(floorMatch[1] || floorMatch[2]) : null;
      const ceiling = ceilingMatch ? parseNum(ceilingMatch[1] || ceilingMatch[2]) : null;
      if (ceiling !== null) {
        hi = ceiling;
        if (lo > hi) lo = Math.trunc(hi * (1 - tol));
      }
      if (floor !== null && (hi === null || floor <= hi)) lo = Math.max(lo, floor);
      const newLow = Math.max(low, lo);
      const newHigh = hi === null ? high : (high === null ? hi : Math.min(high, hi));
      if (newHigh !== null && newLow > newHigh) continue;
      found = true;
      low = newLow;
      high = newHigh;
    }
    return found && plain <= 1 ? [unit, low, high] : null;
  })();
  if (target === null) return { id: 'length', passed: true, severity: 'low', detail: 'no word or character count requested', suggested_fix: '' };
  const unit = target[0], low = target[1], high = target[2];
  const size = unit === 'words' ? content.split(/\s+/).filter(w => w).length : Array.from(content.trim()).length;
  const allowed = high === null ? 'at least ' + low : (low === 0 ? 'at most ' + high : low + '-' + high);
  if (size >= low && (high === null || size <= high)) return { id: 'length', passed: true, severity: 'low', detail: size + ' ' + unit + ', allowed ' + allowed, suggested_fix: '' };
  return { id: 'length', passed: false, severity: 'high', detail: 'Draft is ' + size + ' ' + unit + '; the brief allows ' + allowed + ' ' + unit + '.', suggested_fix: 'Rewrite to ' + allowed + ' ' + unit + '.' };
})() }}

={{ (() => {
  // Port of harness/checks.py check_key_points: half of a point's 5-letter word stems must appear; a point of only short words ("AI", "ROI") needs the phrase itself.
  const brief = $('Build Draft Input').first().json.brief || {};
  const content = String($json.output.draft.content || '');
  const points = Array.isArray(brief.key_points) ? brief.key_points : [];
  if (!points.length) return { id: 'key_points_covered', passed: true, severity: 'low', detail: 'no key points in brief', suggested_fix: '' };
  const stems = t => (String(t).toLowerCase().match(/[a-z0-9]+/g) || []).filter(w => w.length > 3 || /^\d+$/.test(w)).map(w => w.slice(0, 5));
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const seen = {};
  stems(content).forEach(s => { seen[s] = true; });
  const missing = points.filter(p => {
    const st = stems(p);
    if (st.length) return st.filter(s => seen[s] === true).length / st.length < 0.5;
    const phrase = String(p).trim();
    return phrase !== '' && !new RegExp('(?<!\\w)' + esc(phrase) + '(?!\\w)', 'i').test(content);
  }).map(p => String(p));
  if (!missing.length) return { id: 'key_points_covered', passed: true, severity: 'low', detail: 'ok', suggested_fix: '' };
  return { id: 'key_points_covered', passed: false, severity: 'medium', detail: 'Key points not covered: ' + missing.join('; '), suggested_fix: 'Add a passage addressing each missing key point.' };
})() }}

={{ (() => {
  // Port of harness/checks.py check_citations: one research source must be cited by URL, host, quoted multi-word title, or as a name on word edges.
  const content = String($json.output.draft.content || '');
  const sources = $('Build Draft Input').first().json.sources;
  const pass = detail => ({ id: 'citations_present', passed: true, severity: 'low', detail: detail, suggested_fix: '' });
  if (!Array.isArray(sources) || !sources.length) return pass('no research sources to cite');
  const lowered = content.toLowerCase();
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const norm = t => t.toLowerCase().replace(/[^a-z0-9]/g, '');
  const hostOf = url => {
    const m = /^(?:[a-z][a-z0-9+.-]*:)?\/\/([^\/?#]*)/i.exec(url);
    if (!m) return '';
    let h = m[1].slice(m[1].lastIndexOf('@') + 1);
    h = h.startsWith('[') ? h.slice(1, h.indexOf(']') > 0 ? h.indexOf(']') : h.length) : h.split(':')[0];
    h = h.toLowerCase();
    return h.startsWith('www.') ? h.slice(4) : h;
  };
  const labelOf = host => {
    let p = (host.startsWith('www.') ? host.slice(4) : host).split('.').filter(x => x);
    if (p.length > 2 && p[p.length - 1].length === 2 && ['co', 'com', 'org', 'gov', 'ac'].includes(p[p.length - 2])) p = p.slice(0, -2);
    else if (p.length > 1) p = p.slice(0, -1);
    return p.length ? p[p.length - 1] : '';
  };
  // Whether a label appears as a name: starting and ending on word edges, spanning words ("GM Insights"), a lone word only capitalized.
  const cited = label => {
    const tokens = content.match(/[A-Za-z0-9]+/g) || [];
    const starts = {};
    const ends = {};
    let pos = 0;
    tokens.forEach((w, i) => {
      starts[pos] = i;
      pos += w.length;
      ends[pos] = i;
    });
    const squashed = tokens.join('').toLowerCase();
    for (let at = squashed.indexOf(label); at !== -1; at = squashed.indexOf(label, at + 1)) {
      const first = starts[at];
      const last = ends[at + label.length];
      if (first !== undefined && last !== undefined && (first !== last || /^[A-Z]/.test(tokens[first]))) return true;
    }
    return false;
  };
  const found = sources.some(src => {
    if (!src || typeof src !== 'object' || Array.isArray(src)) return false;
    const url = String(src.url || '');
    const host = url ? hostOf(url) : '';
    const title = String(src.title || '');
    const t = title.trim();
    if ((url && lowered.includes(url.toLowerCase())) || (host && new RegExp('(?<![a-z0-9-])' + esc(host) + '(?![a-z0-9-])').test(lowered))) return true;
    if (t.includes(' ') && new RegExp('(?<!\\w)' + esc(t.toLowerCase()) + '(?!\\w)').test(lowered)) return true;
    const label = norm(labelOf(host));
    const name = norm(title);
    // A lone-word title ("Home") is too common to prove a citation: it needs six letters.
    const nameOk = name.length >= (t.includes(' ') ? 4 : 6);
    return (label.length >= 4 && cited(label)) || (nameOk && cited(name));
  });
  if (found) return pass('ok');
  return { id: 'citations_present', passed: false, severity: 'medium', detail: 'Research was used but the draft cites none of its sources.', suggested_fix: 'Cite at least one source (title or URL) for the claims taken from research.' };
})() }}

={{ (() => {
  // Port of harness/checks.py check_format: a brief that asks for markdown needs at least one heading.
  const brief = $('Build Draft Input').first().json.brief || {};
  const content = String($json.output.draft.content || '');
  if (!String(brief.format || '').toLowerCase().includes('markdown')) return { id: 'format', passed: true, severity: 'low', detail: 'markdown structure not required', suggested_fix: '' };
  if (/^#{1,6}\s+\S/m.test(content)) return { id: 'format', passed: true, severity: 'low', detail: 'ok', suggested_fix: '' };
  return { id: 'format', passed: false, severity: 'low', detail: 'Markdown was requested but the draft has no headings.', suggested_fix: 'Add markdown headings.' };
})() }}

={{ (() => {
  const req = String($('Build Draft Input').first().json.raw_request || '');
  const content = String($json.output.draft.content || '');
  const wc = content.trim().split(/\s+/).filter(w => w.length > 0).length;
  const out = [];
  const numWords = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
  const toNum = s => { const k = String(s).toLowerCase().replace(/,/g, ''); return numWords[k] || parseInt(k, 10) || 0; };
  const ending = req.match(/end(?:s|ing)?\s+(?:with|on)\s+the\s+(?:sentence|phrase|line|words?)\s*:?\s*(?:"([^"]+)"|“([^”]+)”|'([^']+)')/i);
  const target = ending ? (ending[1] || ending[2] || ending[3]) : '';
  if (target) {
    const trim = s => s.trim().replace(/[\s*_"“”']+$/, '');
    if (!trim(content).endsWith(trim(target))) out.push('The draft must end with the sentence "' + target.trim() + '" and nothing after it.');
  }
  const exact = /exactly\s+(\d[\d,]*)\s+words?/i.exec(req);
  if (exact && !/\b(?:each|every|per)\b[^.;\n]{0,60}$/i.test(req.slice(0, exact.index))) {
    const n = parseInt(exact[1].replace(/,/g, ''), 10);
    if (Math.abs(wc - n) > Math.max(5, n * 0.05)) out.push('The request asks for exactly ' + n + ' words; the draft has ' + wc + ' (allowed ' + Math.round(n * 0.95) + '-' + Math.round(n * 1.05) + ').');
  }
  const bul = req.match(/bullet(?:ed)?\s+list\s+of\s+at\s+least\s+(\w+)/i) || req.match(/at\s+least\s+(\w+)\s+bullet(?:ed)?/i);
  if (bul) {
    const n = toNum(bul[1]);
    const have = (content.match(/^\s*(?:[-*•]|\d+[.)])\s+\S/gm) || []).length;
    if (n > 0 && have < n) out.push('The request asks for at least ' + n + ' bullet items; the draft has ' + have + '.');
  }
  return out;
})() }}

parameters.text:
=Incoming message on wire `DraftAgent_to_ReviewAgent` (revision_round {{ $json.round }}).

Brief:
{{ JSON.stringify($json.brief, null, 2) }}

Draft title: {{ $json.draft.title }}
Draft (markdown):
{{ $json.draft.content }}

Deterministic checks computed by the workflow (treat as facts):
- measured word_count: {{ $json.word_count }} (draft self-reported {{ $json.draft.word_count ?? 'none' }})
{{ [$json.length_check, $json.key_points_check, $json.citations_check, $json.format_check].map(c => '- ' + c.id + ': ' + (c.passed ? 'passed' : 'failed') + ' (' + c.detail + ')').join('\n') }}
- placeholder text detected: {{ $json.has_placeholder }}
- explicit request constraints that failed (computed by the workflow, treat as facts): {{ ($json.constraint_failures || []).length ? $json.constraint_failures.join(' | ') : 'none' }}

Original client request (check every explicit requirement in it, not only the brief):
{{ $json.raw_request }}

Evaluate the draft against the brief. Return dimension_scores (clarity, accuracy, completeness, tone_alignment, each 0-100), score (composite 0-100, consistent with the dimensions), requirements (array of requirement + passed boolean), issues (array of severity critical/high/medium/low, description, suggested_fix; empty if nothing to flag) and status (derive it mechanically: "approved" when score >= 80 and no issue is critical or high, else "revision_required"; medium and low issues do not block approval). Flag as high any specific claim (statistic, study, date, contact detail, quote) that is not in the brief or the dossier.

Note: in this n8n workflow you have no callable tools; perform the steps of your workflow yourself and return only the structured result.

