={{ (() => {
  // Every issue gets a boolean `blocking`; Approved? passes only if none blocks.
  const d = $('Deterministic Checks').last().json;
  const r = $json.output || {};
  const s = r.score;
  const scoreOk = typeof s === 'number' && Number.isFinite(s) && s >= 0 && s <= 100;
  const out = [];
  const add = (severity, category, description, suggested_fix, blocking) => out.push({ severity, category, description, suggested_fix, blocking });
  const malformed = (description, fix) => add('critical', 'malformed_review', description, fix, true);
  if (Array.isArray(r.issues)) {
    r.issues.forEach(i => {
      if (i && typeof i === 'object' && !Array.isArray(i)) {
        const sev = String(i.severity || '').toLowerCase();
        out.push(Object.assign({}, i, { blocking: sev === 'critical' || sev === 'high' }));
      } else {
        malformed('ReviewAgent returned an issue that is not an object.', 'Re-run the review and return each issue as an object.');
      }
    });
  } else if (r.issues !== undefined && r.issues !== null) {
    malformed('ReviewAgent returned issues that are not a list.', 'Re-run the review and return issues as a list.');
  }
  (Array.isArray(r.requirements) ? r.requirements : []).forEach(q => {
    // Guides the reviser but does not block: the reviewer's own issue severity decides that.
    if (q && q.passed === false) add('high', 'requirement_failed', 'Requirement not met: ' + (q.requirement || '(unnamed)'), 'Revise the draft so that it meets this requirement.', false);
  });
  if (d.has_placeholder) add('critical', 'deterministic:no_placeholders', 'Placeholder text detected in the draft (e.g. [Insert ...], TODO, TBD, lorem ipsum).', 'Replace every placeholder with real content or remove it.', true);
  // Harness checks: key points, citations and format are medium/low; a missed length is high but does not block,
  // because the free-text length parser misreads some phrasings (issue #9).
  [d.length_check, d.key_points_check, d.citations_check, d.format_check].forEach(c => {
    if (!c || c.passed !== true) {
      const sev = String((c && c.severity) || 'critical').toLowerCase();
      const id = (c && c.id) || 'unknown';
      add(sev, 'deterministic:' + id, (c && c.detail) || 'A deterministic check did not run.', (c && c.suggested_fix) || 'Re-run the workflow.', id !== 'length' && (sev === 'critical' || sev === 'high'));
    }
  });
  (d.constraint_failures || []).forEach(f => add('critical', 'request_constraint', f, 'Revise the draft so that it satisfies this: ' + f, true));
  if (!scoreOk) {
    malformed('ReviewAgent returned a missing, non-numeric or out-of-range score.', 'Re-run the review and return a numeric 0-100 score.');
  } else if (s < 80 && out.length === 0) {
    add('high', 'score_below_threshold', 'ReviewAgent scored the draft ' + s + ', below the 80 threshold, but listed no issues.', 'Strengthen the draft against the brief: accuracy, completeness, tone and structure.', true);
  }
  return out;
})() }}

